class PatchTST_backbone(nn.Module):
    """
    PatchTST_backbone
    """
    def __init__(
        self,
        config,
    ):

        super().__init__()

        self.hidden_size = config.hidden_size
        self.patch_len = config.patch_len

        self.revin = config.revin
        if config.revin:
            self.revin_layer = RevINMultivariate(
                num_features=config.n_series, 
                affine=config.revin_affine, 
                subtract_last=config.revin_subtract_last,
            )

        self.padding_patch = config.padding_patch
        patch_num = int((config.input_size - config.patch_len) / config.stride + 1)
        if config.padding_patch == "end":  # can be modified to general case
            self.padding_patch_layer = nn.ReplicationPad1d((0, config.stride))
            patch_num += 1
        self.patch_num = patch_num

        self.tokenizer = Patching(
            patch_len=config.patch_len, 
            stride=config.stride,
        )

        self.W_P = nn.Linear(
            config.patch_len, config.hidden_size
        )  # Eq 1: projection of feature vectors onto a d-dim vector space

        # Positional encoding
        self.W_pos = PositionalEncoding(
            pe_type=config.pe_type,
            hidden_size=config.hidden_size,
            learn_pe=config.learn_pe,
        )
        # Residual dropout
        self.dropout = nn.Dropout(config.dropout)

        self.encoder = TSTEncoder(config=config)

        # Prediction Head
        self.head = Flatten_Head(
            multivariate_head=config.multivariate_head,
            n_vars=config.n_series,
            nf=config.hidden_size * patch_num,
            h=config.h,
            c_out=config.c_out,
            head_dropout=config.head_dropout,
        )

    def forward(self, x_enc : torch.Tensor):  # z: [bs x nvars x seq_len]

        batch_size, n_channels, seq_len = x_enc.shape

        # Normalization (applied over axis=1)
        if self.revin:
            x_enc = x_enc.permute(0, 2, 1) # [batch_size x seq_len x n_channel]
            x_enc = self.revin_layer(x_enc, "norm")
            x_enc = x_enc.permute(0, 2, 1) # [batch_size x n_channel x seq_len]
        
        # Patching
        if self.padding_patch == "end":
            x_enc = self.padding_patch_layer(x_enc) 
        x_enc = self.tokenizer(x=x_enc) # [batch_size x n_channels x n_patch x patch_len]

        # Embeddings
        x_enc = self.W_P(x_enc) # [batch_size x n_channels x n_patch x d_model]
        x_enc += self.W_pos(x_enc) # [batch_size x n_channels x n_patch x d_model]
        
        x_enc = x_enc.reshape(
            (batch_size * n_channels, self.patch_num, self.hidden_size)) # [batch_size*n_channels, n_patch, d_model]
        x_enc = self.dropout(x_enc) # [batch_size*n_channels, n_patch, d_model]

        # Encoder
        enc_out = self.encoder(src=x_enc, n_channels=n_channels)  # z: [bs x nvars x patch_num x hidden_size]
        enc_out = enc_out.reshape(
            (batch_size, n_channels, self.patch_num, self.hidden_size)
        ) # [batch_size, n_channels, n_patch, d_model]
        
        # Decoder
        dec_out = self.head(enc_out)  # z: [bs x nvars x h]

        # De-Normalization
        if self.revin:
            dec_out = dec_out.permute(0, 2, 1) # [batch_size x horizon*c_out x n_channel]
            dec_out = self.revin_layer(dec_out, "denorm")
            dec_out = dec_out.permute(0, 2, 1) # [batch_size x n_channel x horizon*c_out]

        return dec_out

class TSTEncoder(nn.Module):
    """
    TSTEncoder
    """
    def __init__(
        self,
        config,
    ):
        super().__init__()

        if config.infini_mixer_type == 'betas':
            if config.layerwise_beta:
                beta = None
            else:
                # Create a shared beta
                if config.channelwise_beta:
                    beta = nn.Parameter(torch.rand((1, config.n_series, config.n_heads, 1, 1))*1e-2)
                else:
                    beta = nn.Parameter(torch.rand((1, 1, config.n_heads, 1, 1))*1e-2)
                # Adjust the values to ensure they sum to 0
                with torch.no_grad():
                    beta -= beta.mean(dim=2, keepdim=True)
        else:
            beta=None

        self.layers = nn.ModuleList(
            [
                TSTEncoderLayer(
                    config=config,
                    beta=beta,
                )
                for i in range(config.n_layers)
            ]
        )
        self.res_attention = config.res_attention

    def forward(
        self,
        src: torch.Tensor,
        n_channels: int,
        key_padding_mask: Optional[torch.Tensor] = None,
        attn_mask: Optional[torch.Tensor] = None,
    ):
        output = src
        scores = None
        if self.res_attention:
            for mod in self.layers:
                output, scores = mod(
                    src=output,
                    n_channels=n_channels,
                    prev=scores,
                    key_padding_mask=key_padding_mask,
                    attn_mask=attn_mask,
                )
            return output
        else:
            for mod in self.layers:
                output = mod(
                    src=output, 
                    n_channels=n_channels,
                    key_padding_mask=key_padding_mask, 
                    attn_mask=attn_mask
                )
            return output

class TSTEncoderLayer(nn.Module):
    """
    TSTEncoderLayer
    """
    def __init__(
        self,
        config,
        beta: Optional[torch.Tensor] = None,
    ):
        super().__init__()

        # Multi-Head attention
        self.res_attention = config.res_attention
        self.self_attn = MultiheadAttention(
            config=config,
            beta=beta,
        )

        # Add & Norm
        self.dropout_attn = nn.Dropout(config.dropout)
        if "batch" in config.norm.lower():
            self.norm_attn = nn.Sequential(
                Transpose(1, 2), nn.BatchNorm1d(config.hidden_size), Transpose(1, 2)
            )
        else:
            self.norm_attn = nn.LayerNorm(config.hidden_size)

        # Position-wise Feed-Forward
        self.ff = nn.Sequential(
            nn.Linear(config.hidden_size, config.linear_hidden_size, bias=True), # bias hard-coded in PatchTST
            get_activation_fn(config.activation),
            nn.Dropout(config.dropout),
            nn.Linear(config.linear_hidden_size, config.hidden_size, bias=True), # bias hard-coded in PatchTST
        )

        # Add & Norm
        self.dropout_ffn = nn.Dropout(config.dropout)
        if "batch" in config.norm.lower():
            self.norm_ffn = nn.Sequential(
                Transpose(1, 2), nn.BatchNorm1d(config.hidden_size), Transpose(1, 2)
            )
        else:
            self.norm_ffn = nn.LayerNorm(config.hidden_size)

        self.pre_norm = config.pre_norm
        self.store_attn = config.store_attn

    def forward(
        self,
        src: torch.Tensor,
        n_channels: int,
        prev: Optional[torch.Tensor] = None,
        key_padding_mask: Optional[torch.Tensor] = None,
        attn_mask: Optional[torch.Tensor] = None,
    ):  # -> Tuple[torch.Tensor, Any]:

        # Multi-Head attention sublayer
        if self.pre_norm:
            src = self.norm_attn(src)
        ## Multi-Head attention
        if self.res_attention:
            src2, attn, scores = self.self_attn(
                n_channels=n_channels,
                Q=src,
                K=src,
                V=src,
                prev=prev,
                key_padding_mask=key_padding_mask,
                attn_mask=attn_mask,
            )
        else:
            src2, attn = self.self_attn(
                n_channels=n_channels,
                Q=src,
                K=src,
                V=src,
                key_padding_mask=key_padding_mask,
                attn_mask=attn_mask,
            )
        if self.store_attn:
            self.attn = attn
        ## Add & Norm
        src = src + self.dropout_attn(
            src2
        )  # Add: residual connection with residual dropout
        if not self.pre_norm:
            src = self.norm_attn(src)

        # Feed-forward sublayer
        if self.pre_norm:
            src = self.norm_ffn(src)
        ## Position-wise Feed-Forward
        src2 = self.ff(src)
        ## Add & Norm
        src = src + self.dropout_ffn(
            src2
        )  # Add: residual connection with residual dropout
        if not self.pre_norm:
            src = self.norm_ffn(src)

        if self.res_attention:
            return src, scores
        else:
            return src

